import {questions,subjects,shuffledOptions} from './questions.js';
import {drawWorld} from './world.js';
import {loadAllArt,loadArt,heroes,companions} from './art.js';
import {maps,difficultyLabels,freshProgress,validProgress,newBattle,settle,award,makeDeck} from './academy-core.js';
const $=id=>document.getElementById(id),KEY='anhoa-academy-v3',panel=$('panel'),quiz=$('quiz'),video=$('intro-video');
let progress=freshProgress(),saveFailed=false;
try{const raw=localStorage.getItem(KEY);if(raw)progress=validProgress(JSON.parse(raw));}catch{saveFailed=true;}
let mapIndex=progress.unlocked,battle=null,phase='ready',effect=null,visualWave=null,shieldAt=-1,deck=[],q=null,options=[],remaining=0,lastTick=0,interval=null,training=false,pausedPhase='question',audio=null,autoResumeVideo=false,routeSignature='',panelClose=null;
const state={cls:progress.hero,element:1,pet:1,zone:0,wins:[0,0,0],background:maps[mapIndex].background};
const heroNames=['Pháp sư nhỏ','Vệ sĩ dũng cảm','Bạn của linh thú'];
function save(){try{localStorage.setItem(KEY,JSON.stringify(progress));saveFailed=false;}catch{saveFailed=true;}renderSave();}
function renderSave(){$('save-status').textContent=saveFailed?'Chưa lưu được trên máy':'Đã lưu trên máy';$('save-status').classList.toggle('save-warning',saveFailed);}
function tone(kind){if(!progress.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const notes=kind==='win'?[523,659,784,1046]:kind==='correct'?[659,880]:[330,262];notes.forEach((f,i)=>{const t=audio.currentTime+i*.13,o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.06,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.35);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.36);});}catch{/* Sound is optional. */}}
function setMessage(s){$('message').textContent=s;}
function render(){const map=maps[mapIndex];state.cls=progress.hero;state.element=map.element;state.pet=map.pet;state.background=map.background;
 $('chapter-number').textContent=`CHƯƠNG ${String(mapIndex+1).padStart(2,'0')} / 05`;$('map-name').textContent=map.name;$('map-place').textContent=map.place;
 $('fragments').textContent=progress.stars.filter(Boolean).length+' / 5 mảnh ghép';$('level-chip').textContent='Lớp 2 · '+difficultyLabels[progress.difficulty];
 $('wave-label').textContent=battle?`Lượt ${battle.turn+1} · ${battle.wave?'Người giữ mảnh ghép':'Dọn đường'}`:'Chuẩn bị lên đường';
 $('enemy-name').textContent=battle?.wave?map.friend:'Linh thể lạc đường';$('fog-fill').style.width=(battle?battle.hp/battle.maxHp*100:100)+'%';$('fog-label').textContent=battle?`${battle.hp} / ${battle.maxHp} lớp sương`:'Sương mù';
 const shield=battle?.shield??3;$('shield').textContent='◆ '.repeat(shield)+'◇ '.repeat(3-shield);$('shield').setAttribute('aria-label',shield+' lá chắn');
 $('pet-image').src=`assets/${companions[map.pet]}.webp`;$('pet-image').alt=['Thiết Vũ','Mộc Miên','Giọt Mưa','Đốm Lửa','Đá Nhỏ'][map.pet];
 $('hero-image').src=`assets/${heroes[progress.hero]}.webp`;$('hero-image').alt=heroNames[progress.hero];$('hero-name').textContent=heroNames[progress.hero];$('total-correct').textContent=progress.correct;$('total-stars').textContent=progress.stars.reduce((a,b)=>a+b,0);
 $('attack').disabled=phase!=='ready';$('attack').textContent=battle?'Trả lời & ra chiêu →':'Bắt đầu khám phá →';
 for(const id of ['settings-open','journey-open','guide-open','parent-open'])$(id).disabled=phase!=='ready';
 $('sound').setAttribute('aria-label',progress.sound?'Tắt âm thanh':'Bật âm thanh');$('sound').setAttribute('aria-pressed',String(progress.sound));$('sound').style.opacity=progress.sound?'1':'.6';
 const sig=[progress.unlocked,mapIndex,progress.stars.join(),phase==='ready'].join('|');if(sig!==routeSignature){routeSignature=sig;$('route-strip').replaceChildren();maps.forEach((m,i)=>{const b=document.createElement('button');b.className='route-node'+(i===mapIndex?' active':'');b.disabled=i>progress.unlocked||phase!=='ready';b.setAttribute('aria-label',`${i+1}. ${m.name}${i>progress.unlocked?' · Chưa mở':''}`);b.innerHTML=`<img src="assets/${m.background}.webp" alt=""><span><b>${i+1}. ${m.name}</b><small>${i>progress.unlocked?'Chưa mở':progress.stars[i]?'★'.repeat(progress.stars[i]):'Khám phá'}</small></span>`;b.onclick=()=>chooseMap(i);$('route-strip').append(b);});}renderSave();}
function openPanel(html,onClose=null){panelClose=onClose;$('panel-content').innerHTML=html;if(!panel.open)panel.showModal();}
function closePanel(){panel.close();const fn=panelClose;panelClose=null;if(fn)fn();else if(phase==='ready')$('attack').focus();}
$('panel-close').onclick=closePanel;panel.addEventListener('cancel',e=>{e.preventDefault();closePanel();});
function chooseMap(i){if(phase!=='ready'||i>progress.unlocked)return;const go=()=>{mapIndex=i;battle=null;effect=null;setMessage(maps[i].intro);render();};if(battle){openPanel('<p class="eyebrow">ĐỔI CHẶNG ĐƯỜNG</p><h2 id="panel-title">Về bản đồ khác?</h2><p>Trận đang chơi sẽ bắt đầu lại. Các mảnh ghép đã nhận vẫn được giữ.</p><div class="panel-actions"><button id="confirm-map" class="primary full">Đổi bản đồ</button><button id="cancel-map" class="quiet">Ở lại đây</button></div>');$('confirm-map').onclick=()=>{panel.close();go();};$('cancel-map').onclick=closePanel;}else go();}
function startBattle(){if(phase!=='ready')return;if(!progress.tutorialDone){tutorial(0);return;}battle=newBattle(mapIndex);setMessage(maps[mapIndex].intro);render();ask();}
function updateTimer(){if(!q)return;const total=progress.pace*1000;$('timer').textContent=total?Math.max(0,Math.ceil(remaining/1000))+' giây':'Không vội nhé';$('timer-fill').style.width=total?Math.max(0,remaining/total*100)+'%':'100%';}
function startClock(){clearInterval(interval);lastTick=performance.now();if(progress.pace&&!training)interval=setInterval(()=>{const now=performance.now();if(!document.hidden&&phase==='question')remaining-=now-lastTick;lastTick=now;updateTimer();if(remaining<=0&&phase==='question')answer(-1);},100);}
function ask(trial=false){if(!trial&&phase!=='ready')return;training=trial;
 if(trial)q={id:'tutorial',subject:'math',topic:'Cùng thử một lần',prompt:'Mộc Miên có 2 chiếc lá, em tặng thêm 1 chiếc. Bạn ấy có tất cả mấy chiếc lá?',options:['3 chiếc lá','1 chiếc lá','2 chiếc lá','4 chiếc lá'],answer:0,explanation:'2 chiếc lá thêm 1 chiếc lá là 3 chiếc lá.'};
 else{if(!deck.length)deck=makeDeck(questions,progress.subject,progress.difficulty);q=deck.pop();}
 options=shuffledOptions(q);phase='question';remaining=progress.pace*1000;
 $('qsubject').textContent=training?'CÙNG MỘC MIÊN LUYỆN TẬP':'Lớp 2 · '+subjects[q.subject];$('qtopic').textContent=training?'BẤM VÀO ĐÁP ÁN EM CHỌN':difficultyLabels[progress.difficulty]+' · '+q.topic;
 $('question').textContent=q.prompt;quiz.classList.toggle('long',q.prompt.length>130);$('feedback').textContent='';$('continue').hidden=true;$('leave-question').hidden=training;$('answers').replaceChildren();options.forEach((o,i)=>{const b=document.createElement('button'),badge=document.createElement('em'),label=document.createElement('span');badge.textContent='ABCD'[i];label.textContent=o.text;b.append(badge,label);b.onclick=()=>answer(i);$('answers').append(b);});updateTimer();if(training){$('timer').textContent='Lượt tập · không mất lá chắn';$('timer-fill').style.width='100%';}render();quiz.showModal();quiz.scrollTop=0;$('answers').firstElementChild.focus({preventScroll:true});startClock();}
function answer(index){if(phase!=='question')return;phase='feedback';clearInterval(interval);const correct=options[index]?.correct===true;
 [...$('answers').children].forEach((b,i)=>{b.disabled=true;if(options[i].correct)b.classList.add('correct');else if(i===index)b.classList.add('wrong');});
 $('feedback').textContent=(correct?'Đúng rồi! ':index<0?'Hết giờ rồi. Mình cùng xem nhé. ':'Mình cùng xem lại nhé. ')+q.explanation;
 $('continue').textContent=correct?'Tung phép →':training?'Thử lại cùng Mộc Miên':'Mình đã hiểu →';$('continue').hidden=false;$('leave-question').hidden=true;$('continue').focus();tone(correct?'correct':'wrong');$('continue').onclick=()=>resolve(correct);}
function resolve(correct){if(phase!=='feedback')return;phase='animation';quiz.close();clearInterval(interval);
 if(training){if(!correct){phase='ready';ask(true);return;}effect={time:performance.now(),damage:1,skill:true};setMessage('Tuyệt lắm! Em đã biết cách gửi một phép màu.');render();setTimeout(()=>{progress.tutorialDone=true;save();training=false;phase='ready';openPanel('<div class="panel-center"><img class="tutorial-pet" src="assets/pet-wood.webp" alt="Mộc Miên"><p class="eyebrow">EM ĐÃ SẴN SÀNG</p><h2 id="panel-title">Cùng lên đường nào!</h2><p>Trả lời đúng để xua sương. Nếu chưa đúng, đọc lời giải rồi thử câu tiếp theo nhé.</p><button id="finish-guide" class="primary full">Khám phá Hẻm An Hòa →</button></div>',()=>{render();});$('finish-guide').onclick=()=>{panel.close();panelClose=null;render();startBattle();};render();},850);return;}
 const oldWave=battle.wave;visualWave=oldWave;battle=settle(battle,correct);progress.attempts++;if(correct)progress.correct++;save();
 if(correct){effect={time:performance.now(),damage:1,skill:true};setMessage(['Một lớp sương đã tan!','Linh thú đã nghe thấy em rồi.','Phép màu đang sáng hơn!'][battle.correct%3]);$('scene-feedback').textContent='Một lớp sương tan biến';}
 else{shieldAt=performance.now();setMessage('Linh thú đã đỡ đòn giúp em. Cùng thử câu tiếp theo nhé.');$('scene-feedback').textContent='Lá chắn đã đỡ đòn';}
 render(); // Keep the struck creature visible while its hit effect plays.
 setTimeout(()=>{visualWave=null;$('scene-feedback').textContent='';if(battle.status==='won'){progress=award(progress,battle);save();phase='result';showResult(true);}else if(battle.status==='lost'){phase='result';showResult(false);}else if(oldWave!==battle.wave){battle.status='active';phase='ready';openPanel(`<p class="eyebrow">CHẶNG CUỐI CỦA BẢN ĐỒ</p><h2 id="panel-title">${maps[mapIndex].friend} đang đợi</h2><p>Em đã dọn xong đường. Còn 4 lớp sương quanh người giữ mảnh ghép.</p><button id="next-wave" class="primary full">Tiến lên →</button>`,()=>render());$('next-wave').onclick=()=>{panel.close();panelClose=null;render();ask();};}else phase='ready';render();},correct?850:700);}
function showResult(won){const map=maps[mapIndex],all=progress.stars.every(Boolean);tone(won?'win':'wrong');openPanel(`<div class="panel-center"><p class="eyebrow">${won?'MẢNH GHÉP ĐÃ TRỞ VỀ':'NGHỈ MỘT CHÚT NHÉ'}</p><h2 id="panel-title">${won?(all?'An Hòa đã thức giấc!':map.relic):'Mình cùng thử lại'}</h2><div class="result-stars">${won?'★'.repeat(Math.max(1,3-battle.mistakes)):'◇ ◇ ◇'}</div><p>${won?map.outro:'Có những câu cần thêm một lần làm quen. Những điều em đã học vẫn ở lại cùng em.'}</p><p class="notice">${battle.correct} câu đúng · ${battle.mistakes} lần cần ôn lại</p><div class="panel-actions"><button id="result-next" class="primary full">${won?(all?'Xem hành trình':'Đến bản đồ tiếp theo →'):'Thử lại bản đồ'}</button><button id="result-back" class="quiet">Về hành trình</button></div></div>`,()=>{phase='ready';battle=null;render();});$('result-next').onclick=()=>{panel.close();panelClose=null;phase='ready';battle=null;if(won&&all){render();journey();}else if(won){mapIndex=Math.min(4,mapIndex+1);render();setMessage(maps[mapIndex].intro);startBattle();}else{render();startBattle();}};$('result-back').onclick=()=>{panel.close();panelClose=null;phase='ready';battle=null;render();journey();};}
function pause(){if(!['question','feedback'].includes(phase)||training)return;pausedPhase=phase;phase='paused';clearInterval(interval);quiz.close();openPanel('<p class="eyebrow">TẠM DỪNG</p><h2 id="panel-title">Mộc Miên sẽ đợi em.</h2><p>Câu hỏi và thời gian còn lại được giữ nguyên.</p><div class="panel-actions"><button id="resume" class="primary full">Tiếp tục câu hỏi</button><button id="retreat" class="quiet">Kết thúc trận này</button></div>',resume);$('resume').onclick=resume;$('retreat').onclick=()=>{panel.close();panelClose=null;phase='ready';battle=null;render();setMessage('Khi sẵn sàng, mình lại lên đường nhé.');};}
function resume(){panel.close();panelClose=null;phase=pausedPhase;quiz.showModal();if(phase==='question')startClock();}
quiz.addEventListener('cancel',e=>{e.preventDefault();pause();});$('leave-question').onclick=pause;
function tutorial(step){const content=[['Chào em, mình là Mộc Miên!','An Hòa đang chìm trong sương. Mỗi câu trả lời đúng sẽ giúp mình gửi một phép màu.'],['Chọn một trong bốn đáp án','Đọc câu hỏi, rồi bấm câu em chọn. Nếu chưa đúng, mình sẽ cùng em xem lời giải.'],['Giữ ba chiếc lá chắn','Mỗi lần chưa đúng, linh thú đỡ một đòn. Hết lá chắn thì thử lại, các mảnh ghép đã nhận không bị mất.']];phase='tutorial';render();openPanel(`<div class="panel-center"><img class="tutorial-pet" src="assets/pet-wood.webp" alt="Mộc Miên"><div class="step-dots">${content.map((_,i)=>`<i class="${i===step?'on':''}"></i>`).join('')}</div><h2 id="panel-title">${content[step][0]}</h2><p>${content[step][1]}</p><button id="guide-next" class="primary full">${step===2?'Thử gửi một phép màu':'Tiếp theo →'}</button></div>`,()=>{phase='ready';progress.tutorialDone=true;save();render();});$('guide-next').onclick=()=>{panel.close();panelClose=null;if(step<2)tutorial(step+1);else{phase='ready';ask(true);}};}
function journey(){if(phase!=='ready')return;openPanel('<p class="eyebrow">NĂM MẢNH TRI THỨC</p><h2 id="panel-title">Hành trình của em</h2><div class="map-list" id="map-list"></div><p class="notice">Hoàn thành bản đồ để mở vùng đất kế tiếp. Em có thể chơi lại những nơi đã mở.</p>');maps.forEach((m,i)=>{const b=document.createElement('button');b.disabled=i>progress.unlocked;b.innerHTML=`<img src="assets/${m.background}.webp" alt=""><span><b>${i+1}. ${m.name}</b><small>${i>progress.unlocked?'Chưa mở':progress.stars[i]?'★'.repeat(progress.stars[i]):m.place}</small></span>`;b.onclick=()=>{panel.close();chooseMap(i);};$('map-list').append(b);});}
function settings(){if(phase!=='ready')return;openPanel(`<p class="eyebrow">CHƠI THEO NHỊP CỦA EM</p><h2 id="panel-title">Tùy chọn</h2><div class="settings-grid"><label>Môn học<select id="subject"><option value="all">Cả bốn môn</option>${Object.entries(subjects).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>Mức câu hỏi<select id="difficulty">${Object.entries(difficultyLabels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>Nhân vật<select id="hero">${heroNames.map((t,i)=>`<option value="${i}">${t}</option>`).join('')}</select></label><label>Thời gian<select id="pace"><option value="0">Không giới hạn</option><option value="15">Thử thách 15 giây</option></select></label></div><p class="notice">Với câu đọc dài, em có thể chọn không giới hạn thời gian. Đổi tùy chọn không làm mất mảnh ghép.</p><div class="panel-actions"><button id="apply-settings" class="primary full">Lưu tùy chọn</button><button id="replay-story" class="quiet">Xem lại câu chuyện</button><button id="replay-guide" class="quiet">Xem hướng dẫn</button></div>`);for(const id of ['subject','difficulty','hero','pace'])$(id).value=String(progress[id]);$('apply-settings').onclick=()=>{progress.subject=$('subject').value;progress.difficulty=$('difficulty').value;progress.hero=Number($('hero').value);progress.pace=Number($('pace').value);deck=[];save();panel.close();render();};$('replay-story').onclick=()=>{panel.close();showIntro();};$('replay-guide').onclick=()=>{panel.close();tutorial(0);};}
function parents(){openPanel('<p class="eyebrow">DÀNH CHO PHỤ HUYNH</p><h2 id="panel-title">Học bằng những bước nhỏ</h2><p>300 câu: 100 Dễ, 100 Bình thường, 100 Khó. Toán 120 câu; ba môn còn lại mỗi môn 60 câu. Có các biến thể cùng dạng bài, không phải 300 mục tiêu học tập khác nhau.</p><p class="notice">Câu hỏi tự biên soạn và tự kiểm tra; chưa được giáo viên thẩm định, chưa đối chiếu đầy đủ mọi trang PDF hoặc xác nhận ấn bản 2026. Tiếng Anh là nội dung làm quen tự chọn. Độ khó là mức đề xuất, không dùng kết quả chơi để kết luận năng lực của trẻ.</p><p><a href="question-bank.json" download>Tải JSON</a> · <a href="question-bank.csv" download>Tải bảng CSV</a> · <a href="sources.html">Nguồn và phạm vi</a></p><p class="notice">Tiến độ bản đồ lưu trên trình duyệt này. Trận đang chơi bắt đầu lại khi tải lại trang. Không yêu cầu tên, email hoặc tài khoản. Bản mở đầu là phim minh họa 10 giây; hình nền được tạo với AI, hiệu ứng và giao diện được lập trình cho game.</p>');}
function showIntro(){phase='intro';render();video.currentTime=0;video.muted=!progress.sound;$('play-intro').disabled=false;$('play-intro').textContent='Xem câu chuyện · 10 giây';$('story').showModal();}
function finishIntro(){video.pause();$('story').close();progress.introSeen=true;save();phase='ready';if(!progress.tutorialDone)tutorial(0);else render();}
$('play-intro').onclick=async()=>{video.muted=!progress.sound;try{await video.play();$('play-intro').disabled=true;$('play-intro').textContent='Đang kể chuyện…';}catch{$('play-intro').textContent='Chạm để phát lại';}};
video.addEventListener('timeupdate',()=>{const t=video.currentTime;$('film-time').textContent=`00:${String(Math.min(10,Math.floor(t))).padStart(2,'0')} / 00:10`;$('story-title').textContent=t<3.4?'Khi thành phố quên mất tên mình…':t<6.7?'Một người bạn nhỏ đã tìm đến.':'Năm mảnh tri thức. Một bình minh.';$('story-caption').textContent=t<3.4?'Một màn sương lạ làm những linh thú lạc đường.':t<6.7?'“Em có muốn cùng mình giúp An Hòa không?”':'Mỗi câu trả lời đúng sẽ thắp sáng một phần thành phố.';});video.onended=finishIntro;video.onerror=()=>{$('play-intro').textContent='Video chưa tải được · thử lại';};$('skip-intro').onclick=finishIntro;$('story').addEventListener('cancel',e=>{e.preventDefault();finishIntro();});
document.addEventListener('visibilitychange',()=>{lastTick=performance.now();if(document.hidden&&phase==='intro'&&!video.paused){autoResumeVideo=true;video.pause();}else if(!document.hidden&&autoResumeVideo&&phase==='intro'){autoResumeVideo=false;video.play().catch(()=>{$('play-intro').disabled=false;});}});
$('attack').onclick=()=>battle?ask():startBattle();$('journey-open').onclick=journey;$('settings-open').onclick=settings;$('guide-open').onclick=()=>tutorial(0);$('parent-open').onclick=parents;$('sound').onclick=()=>{progress.sound=!progress.sound;save();render();tone('correct');};
let lastFrame=0;function frame(t){if(!document.hidden&&t-lastFrame>32){const m=maps[mapIndex],f={artId:m.enemies[visualWave??battle?.wave??0],large:!!(visualWave??battle?.wave)};drawWorld($('world'),state,f,effect,t);if(shieldAt>=0&&t-shieldAt<700){const c=$('world').getContext('2d'),p=(t-shieldAt)/700;c.save();c.globalAlpha=Math.sin(p*Math.PI)*.65;c.strokeStyle='#b5e6d1';c.lineWidth=5;c.beginPath();c.ellipse(340,335,65,110,0,0,Math.PI*2);c.stroke();c.restore();}lastFrame=t;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
render();setMessage(maps[mapIndex].intro);Promise.all([loadAllArt(),loadArt('bg-library'),loadArt('bg-rooftop')]).then(([r,a,b])=>{if(!a||!b||r.some(x=>!x.ok))setMessage('Một số hình chưa tải xong. Nếu cảnh trống, em hãy tải lại trang nhé.');});if(!progress.introSeen)showIntro();else if(!progress.tutorialDone)tutorial(0);
